mapper.select:
SELECT t.union_id as "unionId", t1.open_id as "openId", t1.mini_open_id as "miniOpenId" FROM bs_wx_user_link t left join bs_wx_user t1 on t1.union_id = t.union_id WHERE t.receive_msg = 'Y'
and t.user_id in
#{userId}
and t.user_id = #{userId}
and t.is_active = 'Y' and t1.delete_flag = '0' and t1.open_id is not null
and t.INDUSTRY_CODE = #{industryCode}
UNION ALL SELECT t.union_id as unionId, t1.mini_open_id as openId, t1.mini_open_id as miniOpenId FROM bs_wx_user_link t left join bs_wx_user t1 on t1.union_id = t.union_id WHERE t.receive_msg = 'Y'
and t.user_id in
#{userId}
and t.user_id = #{userId}
and t.is_active = 'Y' and t1.delete_flag = '0' AND t1.MINI_OPEN_ID IS NOT NULL
and t.INDUSTRY_CODE = #{industryCode}
